cache = os.environ["REPRO_DATA_CACHE"]
for name in ["ag_news", "ag_news_csv", "ag_news_csv.tgz", "ag_news_parquet.json",
             "ag_news_test.parquet", "ag_news_train.parquet"]:
    p = os.path.join(cache, name)
    if os.path.isdir(p):
        print(name, "DIR", os.listdir(p))
    elif os.path.isfile(p):
        print(name, "FILE", os.path.getsize(p))
    else:
        print(name, "MISSING")

